/* Offline Chart-compatible canvas renderer for dashboard and reports.
 * Responsive, HiDPI-aware and dependency-free; supports line and bar series. */
(function (global) {
    'use strict';

    const money = (value, decimals = 0) => '₱' + new Intl.NumberFormat('en-PH', {
        minimumFractionDigits: decimals, maximumFractionDigits: decimals,
    }).format(value);

    const shortDate = (label) => {
        const value = String(label ?? '');
        const match = /^(\d{4})-(\d{2})-(\d{2})/.exec(value);
        if (!match) return value.length > 11 ? value.slice(0, 11) + '…' : value;
        const day = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]));
        return Number.isNaN(day.getTime()) ? value : day.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
    };

    const niceStep = (value) => {
        if (!(value > 0)) return 1;
        const power = 10 ** Math.floor(Math.log10(value));
        const fraction = value / power;
        return (fraction <= 1 ? 1 : fraction <= 2 ? 2 : fraction <= 2.5 ? 2.5 : fraction <= 5 ? 5 : 10) * power;
    };

    function Chart(target, config) {
        this.ctx = target && target.canvas ? target : target && target.getContext ? target.getContext('2d') : null;
        if (!this.ctx) throw new TypeError('Expected a canvas or its 2D context');
        this.canvas = this.ctx.canvas;
        this.config = config || {};
        this.destroyed = false;
        this.lastSize = '';
        this.redraw = this.redraw.bind(this);
        this.draw();
        if (typeof ResizeObserver !== 'undefined') {
            this.observer = new ResizeObserver(this.redraw);
            this.observer.observe(this.canvas.parentElement || this.canvas);
        } else {
            global.addEventListener('resize', this.redraw, { passive: true });
        }
        // Tracks resolution changes when moving between monitors or zooming.
        global.addEventListener('resize', this.redraw, { passive: true });
    }

    Chart.prototype.redraw = function () {
        if (!this.destroyed) this.draw();
    };

    Chart.prototype.draw = function () {
        if (this.destroyed) return;
        const canvas = this.canvas;
        const box = canvas.getBoundingClientRect();
        const width = Math.max(0, Math.round(box.width || canvas.clientWidth));
        const height = Math.max(0, Math.round(box.height || canvas.clientHeight));
        if (width < 30 || height < 30) return;
        const dpr = Math.min(3, Math.max(1, global.devicePixelRatio || 1));
        const signature = `${width}:${height}:${dpr}`;
        if (this.lastSize !== signature || canvas.width !== Math.round(width * dpr) || canvas.height !== Math.round(height * dpr)) {
            canvas.width = Math.round(width * dpr);
            canvas.height = Math.round(height * dpr);
            this.lastSize = signature;
        }
        const ctx = this.ctx;
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        ctx.clearRect(0, 0, width, height);
        const data = this.config.data || {};
        const labels = Array.isArray(data.labels) ? data.labels : [];
        const series = Array.isArray(data.datasets) ? data.datasets : [];
        const numbers = series.flatMap((set) => (set.data || []).map(Number).filter(Number.isFinite));
        const color = '#64748b';
        ctx.font = '12px system-ui, -apple-system, Segoe UI, sans-serif';
        if (!labels.length || !numbers.length) {
            ctx.fillStyle = color;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText('No paid sales data for this period', width / 2, height / 2);
            return;
        }

        const largest = Math.max(0, ...numbers);
        const smallest = Math.min(0, ...numbers);
        const step = niceStep(Math.max((largest - smallest) / 4, largest / 4, 0.0001));
        const upper = Math.max(step * 4, Math.ceil(largest / step) * step);
        const lower = smallest < 0 ? Math.floor(smallest / step) * step : 0;
        const range = Math.max(1e-9, upper - lower);
        const decimals = step < 1 ? (step < 0.1 ? 2 : 1) : 0;
        ctx.font = '11px system-ui, -apple-system, Segoe UI, sans-serif';
        const tickCount = Math.min(8, Math.max(2, Math.round(range / step)));
        const tickLabels = Array.from({ length: tickCount + 1 }, (_, i) => money(lower + range * i / tickCount, decimals));
        const tickWidth = Math.max(...tickLabels.map((text) => ctx.measureText(text).width));
        const pad = { top: 24, right: 18, bottom: 37, left: Math.ceil(tickWidth) + 16 };
        const plotWidth = Math.max(1, width - pad.left - pad.right);
        const plotHeight = Math.max(1, height - pad.top - pad.bottom);
        const yAt = (value) => pad.top + plotHeight * (1 - (value - lower) / range);
        const xAt = (index) => labels.length === 1 ? pad.left + plotWidth / 2 : pad.left + index * plotWidth / (labels.length - 1);

        ctx.textBaseline = 'middle';
        for (let i = 0; i <= tickCount; i++) {
            const level = lower + range * i / tickCount;
            const y = yAt(level);
            ctx.beginPath();
            ctx.moveTo(pad.left, y + .5);
            ctx.lineTo(width - pad.right, y + .5);
            ctx.strokeStyle = '#e5eaf1';
            ctx.lineWidth = 1;
            ctx.stroke();
            ctx.fillStyle = '#526579';
            ctx.textAlign = 'right';
            ctx.fillText(tickLabels[i], pad.left - 9, y);
        }

        const labelInterval = Math.max(1, Math.ceil(labels.length / Math.max(1, Math.floor(plotWidth / 72))));
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        labels.forEach((label, index) => {
            if (index % labelInterval && index !== labels.length - 1) return;
            ctx.fillStyle = color;
            ctx.fillText(shortDate(label), xAt(index), height - 16);
        });

        const isBar = this.config.type === 'bar';
        series.forEach((set, seriesIndex) => {
            const stroke = set.borderColor || (seriesIndex % 2 ? '#1d4ed8' : '#0f766e');
            const points = (set.data || []).map((raw, index) => {
                if (raw === null || raw === '' || !Number.isFinite(Number(raw))) return null;
                return { x: xAt(index), y: yAt(Number(raw)) };
            });
            if (isBar) {
                const barWidth = Math.max(3, Math.min(40, plotWidth / (labels.length * Math.max(1, series.length)) * .64));
                ctx.fillStyle = set.backgroundColor || stroke;
                points.forEach((p) => {
                    if (!p) return;
                    const offset = (seriesIndex - (series.length - 1) / 2) * barWidth;
                    ctx.fillRect(p.x - barWidth / 2 + offset, p.y, barWidth, yAt(0) - p.y);
                });
                return;
            }
            const valid = points.filter(Boolean);
            if (!valid.length) return;
            const fill = ctx.createLinearGradient(0, pad.top, 0, pad.top + plotHeight);
            fill.addColorStop(0, 'rgba(15,118,110,.20)');
            fill.addColorStop(1, 'rgba(15,118,110,.012)');
            ctx.beginPath();
            ctx.moveTo(valid[0].x, yAt(0));
            valid.forEach((p) => ctx.lineTo(p.x, p.y));
            ctx.lineTo(valid[valid.length - 1].x, yAt(0));
            ctx.closePath();
            ctx.fillStyle = fill;
            ctx.fill();
            ctx.beginPath();
            valid.forEach((p, index) => index ? ctx.lineTo(p.x, p.y) : ctx.moveTo(p.x, p.y));
            ctx.strokeStyle = stroke;
            ctx.lineWidth = 2.4;
            ctx.lineJoin = 'round';
            ctx.lineCap = 'round';
            ctx.stroke();
            valid.forEach((p) => {
                ctx.beginPath();
                ctx.arc(p.x, p.y, valid.length > 20 ? 2.8 : 4, 0, 2 * Math.PI);
                ctx.fillStyle = '#fff';
                ctx.fill();
                ctx.strokeStyle = stroke;
                ctx.lineWidth = 1.8;
                ctx.stroke();
            });
        });
    };

    Chart.prototype.destroy = function () {
        this.destroyed = true;
        if (this.observer) this.observer.disconnect();
        global.removeEventListener('resize', this.redraw);
    };

    global.Chart = Chart;
})(window);
